// 使用 fs.promises 异步读取和写入文件
const fs = require('fs').promises; // Node.js 内置 promisified 版本

async function readAndWriteFile() {
  try {
    // 读取文件内容
    const data = await fs.readFile('hello.txt', 'utf-8');
    console.log('文件内容:', data);

    // 追加一行内容
    const newContent = data + '\n这行是追加的内容。';
    await fs.writeFile('hello.txt', newContent, 'utf-8');
    console.log('文件写入成功！');

    // 再次读取验证
    const updatedData = await fs.readFile('hello.txt', 'utf-8');
    console.log('更新后的文件内容:', updatedData);
  } catch (err) {
    console.error('操作出错:', err.message);
  }
}

readAndWriteFile();

